lib='''def bbox_halos(grid, marker, fill, box_colors, size=1):
    """Around every marker cell inside the bounding box of any connected component of box_colors, fill a (2*size+1)-square with fill (marker cells kept)."""
    h, w = len(grid), len(grid[0])
    seen = [[False]*w for _ in range(h)]
    boxes = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] in box_colors and not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; r0=r1=i; c0=c1=j
                while stack:
                    a,b=stack.pop()
                    r0=min(r0,a); r1=max(r1,a); c0=min(c0,b); c1=max(c1,b)
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and grid[x][y] in box_colors and not seen[x][y]:
                            seen[x][y]=True; stack.append((x,y))
                boxes.append((r0,r1,c0,c1))
    out=[row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if grid[i][j]==marker and any(r0<=i<=r1 and c0<=j<=c1 for r0,r1,c0,c1 in boxes):
                for a in range(max(0,i-size),min(h,i+size+1)):
                    for b in range(max(0,j-size),min(w,j+size+1)):
                        if out[a][b]!=marker: out[a][b]=fill
    return out
'''
